17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Locale;
26	import java.util.Objects;
27	import java.util.regex.Pattern;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
42	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** Dedicated audit logger; emits an audit line on successful owner create. */
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final AddressNormalizer addressNormalizer;
86	
87	    public OwnerRestControllerV1(ClinicService clinicService,
88	                                 OwnerMapper ownerMapper,
89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper,
91	                                 TelephoneNormalizer telephoneNormalizer,
92	                                 AddressNormalizer addressNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.addressNormalizer = addressNormalizer;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
135	        LocalDate registrationDate = owner.getRegistrationDate();
136	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
137	            .map(Owner::getRegistrationDate)
138	            .filter(registrationDate::equals)
139	            .count();
140	        if (ownersCreatedThatDay >= 100) {
141	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
142	        }
143	        String address = addressNormalizer.normalize(owner.getAddress());
144	        if (address.isBlank()) {
145	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
146	        }
147	        owner.setAddress(address);
148	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
149	        if (telephone == null) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        owner.setTelephone(telephone);
156	        String email = owner.getEmail();
157	        if (email != null) {
158	            email = email.trim();
159	            if (!EMAIL_PATTERN.matcher(email).matches()) {
160	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	            }
162	            owner.setEmail(email.toLowerCase(Locale.ROOT));
163	        }
164	        // The owner's telephone, email and household id are now all in their canonical,
165	        // stored form; establish the household id here so the duplicate check that follows
166	        // sees a fully-normalized owner to compare against the existing ones.
167	        String lastNameKey = normalizeIdentity(owner.getLastName());
168	        String addressKey = addressNormalizer.normalize(owner.getAddress());
169	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
170	        if (isDuplicateOwner(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()))) {
171	            return new ResponseEntity<>(HttpStatus.CONFLICT);
172	        }
173	        String cityKey = normalizeIdentity(owner.getCity());
174	        long ownersInCity = this.clinicService.findAllOwners().stream()
175	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
176	            .count();
177	        if (ownersInCity >= 50) {
178	            return new ResponseEntity<>(HttpStatus.CONFLICT);
179	        }
180	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
181	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
182	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
183	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
184	            .count();
185	        owner.setNamesakeCount(namesakeCount);
186	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
187	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
188	        this.clinicService.saveOwner(owner);
189	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
190	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
191	            ownerMapper.membershipLevel(owner));
192	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
193	        headers.setLocation(UriComponentsBuilder.newInstance()
194	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
195	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    /**
199	     * Whether {@code candidate} collides with an already-registered owner under any of the
200	     * duplicate rules enforced on create. This is the single point at which a new owner is
201	     * rejected as a duplicate (HTTP 409): the candidate clashes when it reuses an existing
202	     * owner's email, reuses an existing owner's telephone, or — unless it is explicitly
203	     * flagged as sharing a household — repeats an existing owner's household (same normalized
204	     * last name and address).
205	     *
206	     * <p>Every comparison is made on the canonical form of the field. The candidate arrives
207	     * with its telephone and email already normalized and its household id already derived,
208	     * and each existing owner's value is reduced the same way before comparison, so a match
209	     * means the two owners are genuinely the same on that field.
210	     *
211	     * @param candidate       the fully-normalized owner about to be created
212	     * @param sharesHousehold whether the caller flagged this owner as intentionally sharing an
213	     *                        existing household, which waives the household duplicate rule
214	     * @return {@code true} if an existing owner already occupies the candidate's identity
215	     */
216	    private boolean isDuplicateOwner(Owner candidate, boolean sharesHousehold) {
217	        Collection<Owner> existingOwners = this.clinicService.findAllOwners();
218	        String email = candidate.getEmail();
219	        if (email != null) {
220	            boolean emailInUse = existingOwners.stream()
221	                .map(Owner::getEmail)
222	                .filter(Objects::nonNull)
223	                .map(existing -> existing.trim().toLowerCase(Locale.ROOT))
224	                .anyMatch(email::equals);
225	            if (emailInUse) {
226	                return true;
227	            }
228	        }
229	        String telephone = candidate.getTelephone();
230	        boolean telephoneInUse = existingOwners.stream()
231	            .map(Owner::getTelephone)
232	            .filter(Objects::nonNull)
233	            .map(telephoneNormalizer::normalize)
234	            .anyMatch(telephone::equals);
235	        if (telephoneInUse) {
236	            return true;
237	        }
238	        if (!sharesHousehold) {
239	            String lastNameKey = normalizeIdentity(candidate.getLastName());
240	            String addressKey = addressNormalizer.normalize(candidate.getAddress());
241	            boolean householdDuplicate = existingOwners.stream()
242	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
243	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
244	            if (householdDuplicate) {
245	                return true;
246	            }
247	        }
248	        return false;
249	    }
250	
251	    /**
252	     * Normalize a value for household-identity comparison: null becomes an empty
253	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
254	     * to a single space, and the result is lower-cased.
255	     */
256	    private static String normalizeIdentity(String value) {
257	        if (value == null) {
258	            return "";
259	        }
